 "content": "from collections import Counter


def _rectangles(grid):
    h, w = len(grid), len(grid[0])
    rects = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(cells) == border:
            rects.append((color, r0, r1, c0, c1))
    return rects


def transform(grid):
    h, w = len(grid), len(grid[0])
    rects = _rectangles(grid)
    framed = {(r, c) for _, r0, r1, c0, c1 in rects
              for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
              if r in (r0, r1) or c in (c0, c1)}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] and (r, c) not in framed)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r, c) not in framed:
                out[r][c] = 0
    for _, r0, r1, c0, c1 in rects:
        interior = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
                    if (r + c) % 2 == 0]
        fill_color = next((color for color, n in counts.items() if n == len(interior)), None)
        if fill_color is not None:
            for r, c in interior:
                out[r][c] = fill_color
    return out
